  const catalog = [];
  const addGroup = (specialty, bodySystem, rows) => {
    const parsed = clean(rows).split(/\r?\n/).map(clean).filter(Boolean).map((row, rowIndex) => {
      const parts = row.split("|").map(clean);
      if (parts.length !== 12) throw new Error(`Wave38 ${specialty} row ${rowIndex + 1} has ${parts.length} fields, expected 12: ${row}`);
      const [name, kind, associated, assessment, positive, mechanism, status, aliases, related, limitations, differentials, pitfalls] = parts;
      return {
        name, kind, specialty, bodySystem, associated, assessment, positive, mechanism, status, limitations, pitfalls,
        aliases: aliases.split(";").map(clean).filter(Boolean),
        related: related.split(";").map(clean).filter(Boolean),
        differentials: differentials.split(";").map(clean).filter(Boolean)
      };
    });
    catalog.push(...parsed);
  };

